(async () => {
      try {
        const list = await api.listSkills(activeWorkdir || ".");
        if (!cancelled) setSkills(list);
      } catch {
        if (!cancelled) setSkills([]);
      }
    })

(() => {
                // streaming 时：输入框有内容 → 按钮做入队（同 Enter）；否则做中断生成。
                const hasDraft = !!value.trim() || attachments.length > 0;
                const enqueueMode = isStreaming && hasDraft;
                const onClick = enqueueMode
                  ? () => enqueueAndClear("tail")
                  : isStreaming
                    ? cancel
                    : submit;
                const buttonDisabled = enqueueMode
                  ? false
                  : isStreaming
                    ? canceling
                    : !canSubmit;
                const title = enqueueMode
                  ? "排队（Enter）"
                  : isStreaming
                    ? "中断生成"
                    : "发送 (Enter)";
                return (
                  <button
                    type="button"
                    onClick={onClick}
                    disabled={buttonDisabled}
                    className={cn(
                      "h-8 w-8 rounded-md inline-flex items-center justify-center bg-transparent text-primary hover:bg-muted disabled:opacity-40 disabled:pointer-events-none",
                      isStreaming &&
                        !enqueueMode &&
                        "bg-background text-primary hover:bg-background"
                    )}
                    title={title}
                  >
                    {enqueueMode ? (
                      <Plus className="w-4 h-4" />
                    ) : isStreaming ? (
                      <LoopingWebm
                        src={animations.assistantThinking}
                        className="h-7 w-7 rounded"
                      />
                    ) : sending ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <img
                        src={animations.assistantThinkingStatic}
                        alt=""
                        className="h-7 w-7 object-contain"
                        draggable={false}
                      />
                    )}
                  </button>
                );
              })

(() => {
        const msg = messages.find((m) => m.id === pinnedUserId);
        if (!msg || msg.role !== "user") return null;
        const prevId = getPrevUserMessageId(pinnedUserId);
        return (
          <div className="pointer-events-none absolute inset-x-0 top-0 z-50">
            <div className="relative bg-background/95 shadow-md backdrop-blur-sm flex items-stretch">
              <button
                type="button"
                onClick={scrollToPinnedMessage}
                title="点击回到此消息"
                className="pointer-events-auto block flex-1 cursor-pointer text-left min-w-0"
              >
                <div className="overflow-hidden [mask-image:linear-gradient(to_bottom,black_60%,transparent)]"
                     style={{ maxHeight: PINNED_HEIGHT_PX }}>
                  <MessageBubble
                    message={msg}
                    prompt={activePrompt}
                    userAvatar={userAvatar}
                    sessionId={currentSession?.id}
                    appSettings={appSettings ?? undefined}
                  />
                </div>
              </button>
              {prevId && (
                <button
                  type="button"
                  onClick={scrollToPrevUserMessage}
                  title="跳转到上一条用户消息"
                  className="pointer-events-auto flex items-center justify-center w-8 shrink-0 text-muted-foreground hover:bg-accent hover:text-foreground transition-colors"
                >
                  <ChevronDown className="h-4 w-4 rotate-180" />
                </button>
              )}
            </div>
          </div>
        );
      })
